function graph_close(set, edges) {
  for (const k of set) {
    edges.forEach(([a, b]) => a === k && set.add(b));
  }
  return set;
}

patches.replacement:
function graph_close(set, edges) {
  const next = new Map();
  edges.forEach(([a, b]) => {
    if (a !== a) return;
    let row = next.get(a);
    if (row === undefined) next.set(a, row = []);
    row.push(b);
  });
  for (const k of set) {
    for (const b of next.get(k) || []) set.add(b);
  }
  return set;
}

